        self.val = val
        self.left = left
        self.right = right


def build_tree(values):
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = [root]
    i = 1
    while i < len(values) and queue:
        node = queue.pop(0)
        if i < len(values):
            if values[i] is not None:
                node.left = TreeNode(values[i])
                queue.append(node.left)
            i += 1
        if i < len(values):
            if values[i] is not None:
                node.right = TreeNode(values[i])
                queue.append(node.right)
            i += 1
    return root


def get_all_leaf_sums(root, current, sums):
    if root is None:
        return
    current += root.val
    if root.left is None and root.right is None:
        sums.append(current)
        return
    get_all_leaf_sums(root.left, current, sums)
    get_all_leaf_sums(root.right, current, sums)


def has_path_sum(root, target_sum):
    if root is None:
        return False
    sums = []
    get_all_leaf_sums(root, 0, sums)
    return target_sum in sums


