import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static TreeNode buildTree(Integer[] values) {
        if (values.length == 0 || values[0] == null) return null;
        TreeNode root = new TreeNode(values[0]);
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        int i = 1;
        while (i < values.length && !queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (i < values.length) {
                if (values[i] != null) {
                    node.left = new TreeNode(values[i]);
                    queue.add(node.left);
                }
                i++;
            }
            if (i < values.length) {
                if (values[i] != null) {
                    node.right = new TreeNode(values[i]);
                    queue.add(node.right);
                }
                i++;
            }
        }
        return root;
    }

    static void getAllLeafSums(TreeNode root, int current, List<Integer> sums) {
        if (root == null) return;
        current += root.val;
        if (root.left == null && root.right == null) {
            sums.add(current);
            return;
        }
        getAllLeafSums(root.left, current, sums);
        getAllLeafSums(root.right, current, sums);
    }

    static boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) return false;
        List<Integer> sums = new ArrayList<>();
        getAllLeafSums(root, 0, sums);
        return sums.contains(targetSum);
    }

    public static void main(String[] args) {
        TreeNode tree1 = buildTree(new Integer[]{5, 4, 8, 11, null, 13, 4, 7, 2, null, null, null, 1});
        System.out.println(hasPathSum(tree1, 22));
        TreeNode tree2 = buildTree(new Integer[]{1, 2, 3});
        System.out.println(hasPathSum(tree2, 5));
    }
}

