#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* buildTree(vector<int>& values, vector<bool>& isNull) {
    if (values.empty() || isNull[0]) return nullptr;
    TreeNode* root = new TreeNode(values[0]);
    queue<TreeNode*> q;
    q.push(root);
    int i = 1;
    while (i < (int)values.size() && !q.empty()) {
        TreeNode* node = q.front(); q.pop();
        if (i < (int)values.size()) {
            if (!isNull[i]) { node->left = new TreeNode(values[i]); q.push(node->left); }
            i++;
        }
        if (i < (int)values.size()) {
            if (!isNull[i]) { node->right = new TreeNode(values[i]); q.push(node->right); }
            i++;
        }
    }
    return root;
}

void getAllLeafSums(TreeNode* root, int current, vector<int>& sums) {
    if (!root) return;
    current += root->val;
    if (!root->left && !root->right) {
        sums.push_back(current);
        return;
    }
    getAllLeafSums(root->left, current, sums);
    getAllLeafSums(root->right, current, sums);
}

bool hasPathSum(TreeNode* root, int targetSum) {
    if (!root) return false;
    vector<int> sums;
    getAllLeafSums(root, 0, sums);
    return find(sums.begin(), sums.end(), targetSum) != sums.end();
}

int main() {
    vector<int> vals1 = {5, 4, 8, 11, 0, 13, 4, 7, 2, 0, 0, 0, 1};
    vector<bool> null1 = {false, false, false, false, true, false, false, false, false, true, true, true, false};
    TreeNode* tree1 = buildTree(vals1, null1);
    cout << boolalpha << hasPathSum(tree1, 22) << endl;
    vector<int> vals2 = {1, 2, 3};
    vector<bool> null2 = {false, false, false};
    TreeNode* tree2 = buildTree(vals2, null2);
    cout << boolalpha << hasPathSum(tree2, 5) << endl;
    return 0;
}

